    public function portal(Request $request)
    {
        $user = $request->user();
        $personnel = LeaveAccess::personnel(LeavePersonnel::where('active', true), $user);
        $stats = cache()->remember('leave.portal.stats.v2.'.(int)$user->id, now()->addSeconds(20), fn () => [
            'personnel' => (clone $personnel)->count(),
            'approved' => (clone LeaveAccess::requests(LeaveRequest::query()->where('status', 'APPROVED'), $user))->count(),
            'pending' => (clone LeaveAccess::requests(LeaveRequest::query()->whereIn('status', ['PENDING','PENDING_COMMANDER','PENDING_AGENCY']), $user))->count(),
        ]);

        return view('portals.leave', compact('stats'));
    }
    public function index(Request $request)
    {
        $user=$request->user();
        $personnel=LeaveAccess::personnel(LeavePersonnel::where('active',true),$user)->with(['user','unitRelation','leaveClass'])->orderBy('name')->get();
        $users=\App\Models\User::query()->where('status',1)->orderBy('name')->get();
        $units=\Modules\Unit\Models\Unit::active()->when(LeaveAccess::isScoped($user),fn($q)=>$q->whereIn('id',LeaveAccess::unitIds($user)))->orderBy('name')->get();
        $classes=LeaveClass::with('unit')->where('active',true)->when(LeaveAccess::isScoped($user),fn($q)=>$q->whereIn('unit_id',LeaveAccess::unitIds($user)))->orderBy('name')->get();
        $objects=LeaveObjectType::where('active',true)->orderBy('sort_order')->get();
        $localities=LeaveLocality::orderBy('name')->get();
        $replacementPersonnel=$personnel;
        $stats = [
            'personnel' => (clone $personnel)->count(),
            'approved' => (clone LeaveAccess::requests(LeaveRequest::query()->where('status', 'APPROVED'), $user))->count(),
            'pending' => (clone LeaveAccess::requests(LeaveRequest::query()->where('status', 'PENDING'), $user))->count(),
        ];
        $requests=LeaveAccess::requests(LeaveRequest::with(['personnel','leaveClass','replacement'])->when($request->status,fn($q,$s)=>$q->where('status',$s)),$user)->latest()->paginate(20)->withQueryString();
        return view('leave-management::index',compact('personnel','replacementPersonnel','requests','users','units','classes','objects','localities','stats'));
    }

